// src/map/east.ts
var TERRAIN_CHARS = {
  "#": Terrain.BUILDING,
  R: Terrain.ROAD,
  S: Terrain.STREET,
  A: Terrain.ALLEY
};
function districtGrid(district) {
  const grid = new Grid(district.width, district.height);
  district.rows.forEach((row, z) => {
    [...row].forEach((char, x) => {
      const terrain = TERRAIN_CHARS[char];
      if (terrain === void 0) throw new Error(`Unknown map character '${char}' at (${x}, ${z}).`);
      grid.terrain[grid.index(x, z)] = terrain;
    });
  });
  return grid;
}
var EAST = east_default;
function loadEast() {
  const lots = EAST.lots.map(([x, z, w, d, floors, color, kind, group]) => ({ x, z, w, d, floors, color, kind, group }));
  return finishCity("east", districtGrid(EAST), lots, []);
}

// src/map/generate.ts
function fill(grid, rect, terrain) {
  for (let z = rect.z; z < rect.z + rect.d; z++) {
    for (let x = rect.x; x < rect.x + rect.w; x++) grid.terrain[grid.index(x, z)] = terrain;
  }
}
function generateCity(rng) {
  const size = MAP.SIZE;
  const road = MAP.ROAD_WIDTH;
  const alley = MAP.ALLEY_WIDTH;
  const grid = new Grid(size, size);
  const roads = [];
  const alleys = [];
  const lots = [];
  roads.push(
    { axis: "x", x: 0, z: 0, w: size, d: road },
    { axis: "x", x: 0, z: size - road, w: size, d: road },
    { axis: "z", x: 0, z: 0, w: road, d: size },
    { axis: "z", x: size - road, z: 0, w: road, d: size }
  );
  const blocks = [];
  const pending = [{ x: road, z: road, w: size - 2 * road, d: size - 2 * road }];
  while (pending.length > 0) {
    const rect = pending.pop();
    if (Math.max(rect.w, rect.d) <= MAP.BLOCK_MAX) {
      blocks.push(rect);
      continue;
    }
    if (rect.w >= rect.d) {
      const at = rng.int(rect.x + MAP.BLOCK_MIN, rect.x + rect.w - MAP.BLOCK_MIN - road);
      roads.push({ axis: "z", x: at, z: rect.z, w: road, d: rect.d });
      pending.push({ ...rect, w: at - rect.x }, { ...rect, x: at + road, w: rect.x + rect.w - at - road });
    } else {
      const at = rng.int(rect.z + MAP.BLOCK_MIN, rect.z + rect.d - MAP.BLOCK_MIN - road);
      roads.push({ axis: "x", x: rect.x, z: at, w: rect.w, d: road });
      pending.push({ ...rect, d: at - rect.z }, { ...rect, z: at + road, d: rect.z + rect.d - at - road });
    }
  }
  const plots = [];
  for (const block of blocks) {
    const long = Math.max(block.w, block.d);
    if (long < MAP.ALLEY_MIN_BLOCK || !rng.chance(MAP.ALLEY_CHANCE)) {
      plots.push(block);
      continue;
    }
    if (block.w >= block.d) {
      const at = rng.int(block.x + 2, block.x + block.w - 2 - alley);
      alleys.push({ axis: "z", x: at, z: block.z, w: alley, d: block.d });
      plots.push({ ...block, w: at - block.x }, { ...block, x: at + alley, w: block.x + block.w - at - alley });
    } else {
      const at = rng.int(block.z + 2, block.z + block.d - 2 - alley);
      alleys.push({ axis: "x", x: block.x, z: at, w: block.w, d: alley });
      plots.push({ ...block, d: at - block.z }, { ...block, z: at + alley, d: block.z + block.d - at - alley });
    }
  }
  const cutLots = (rect) => {
    if (rect.w > MAP.LOT_MAX && rect.w >= rect.d) {
      const at = rng.int(2, rect.w - 2);
      cutLots({ ...rect, w: at });
      cutLots({ ...rect, x: rect.x + at, w: rect.w - at });
    } else if (rect.d > MAP.LOT_MAX) {
      const at = rng.int(2, rect.d - 2);
      cutLots({ ...rect, d: at });
      cutLots({ ...rect, z: rect.z + at, d: rect.d - at });
    } else {
      lots.push({ ...rect, floors: rng.int(MAP.FLOORS_MIN, MAP.FLOORS_MAX), color: rng.int(0, BUILDING_COLORS - 1) });
    }
  };
  plots.forEach(cutLots);
  for (const strip of roads) fill(grid, strip, Terrain.ROAD);
  for (const strip of alleys) fill(grid, strip, Terrain.ALLEY);
  return finishCity("random", grid, lots, alleys);
}

// src/rng.ts
var Rng = class {
  constructor(seed) {
    this.seed = seed;
    this.state = seed >>> 0;
  }
  state;
  /** Uniform in [0, 1). */
  next() {
    this.state = this.state + 1831565813 >>> 0;
    let t = this.state;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
  range(min, max) {
    return min + (max - min) * this.next();
  }
  /** Integer in [min, max], like the original getRandomNum. */
  int(min, max) {
    return Math.floor(this.next() * (max - min + 1)) + min;
  }
  chance(probability) {
    return this.next() < probability;
  }
  pick(items) {
    return items[this.int(0, items.length - 1)];
  }
};

// scripts/check-map.ts
var SEEDS = 500;
var failures = [];
var fail = (label, message) => {
  if (failures.length < 30) failures.push(`${label}: ${message}`);
  else if (failures.length === 30) failures.push("\u2026");
};
function walkableCells(grid) {
  const cells = [];
  for (let cell = 0; cell < grid.cellCount; cell++) if (grid.walkable(cell)) cells.push(cell);
  return cells;
}
function checkStreets(city, label) {
  const { grid } = city;
  const walkable = walkableCells(grid);
  const distance = grid.distances([walkable[0]], () => false, new Int16Array(grid.cellCount));
  const unreached = walkable.filter((cell2) => distance[cell2] < 0).length;
  if (unreached > 0) fail(label, `${unreached} street cells are cut off`);
  for (const cell2 of walkable) {
    const exits = DIRS.filter((dir) => {
      const next = grid.neighbor(cell2, dir);
      return next >= 0 && grid.walkable(next);
    }).length;
    if (exits < 2) fail(label, `dead end at (${grid.x(cell2)}, ${grid.z(cell2)})`);
  }
  let cell = city.spawn.cell;
  if (grid.terrain[cell] !== Terrain.ROAD) fail(label, "spawn is not on a main road");
  for (let i = 1; i < SNAKE.INITIAL_LENGTH; i++) {
    cell = grid.neighbor(cell, opposite(city.spawn.dir));
    if (cell < 0 || !grid.walkable(cell)) fail(label, "initial body does not fit behind the spawn");
  }
  const ahead = grid.neighbor(city.spawn.cell, city.spawn.dir);
  if (ahead < 0 || !grid.walkable(ahead)) fail(label, "spawn faces a wall");
  if (city.entry.length === 0) fail(label, "no ring-road cells for people to walk in from");
  const covered = new Uint8Array(grid.cellCount);
  for (const lot of city.lots) {
    for (let z = lot.z; z < lot.z + lot.d; z++) {
      for (let x = lot.x; x < lot.x + lot.w; x++) {
        const index = grid.index(x, z);
        if (!grid.inside(x, z) || grid.terrain[index] !== Terrain.BUILDING) fail(label, `lot at (${lot.x}, ${lot.z}) covers a street`);
        else if (covered[index]++) fail(label, `lots overlap at (${x}, ${z})`);
      }
    }
  }
  return walkable.length;
}
function checkAlleys(city, label) {
  const { grid } = city;
  const terrainAt = (x, z) => grid.inside(x, z) ? grid.terrain[grid.index(x, z)] : -1;
  for (const alley of city.alleys) {
    const across = alley.axis === "z" ? alley.w : alley.d;
    if (across !== MAP.ALLEY_WIDTH) fail(label, `alley at (${alley.x}, ${alley.z}) is ${across} wide`);
    for (let i = 0; i < across; i++) {
      const ends = alley.axis === "z" ? [terrainAt(alley.x + i, alley.z - 1), terrainAt(alley.x + i, alley.z + alley.d)] : [terrainAt(alley.x - 1, alley.z + i), terrainAt(alley.x + alley.w, alley.z + i)];
      if (ends.some((terrain) => terrain !== Terrain.ROAD)) fail(label, `alley at (${alley.x}, ${alley.z}) ends without a road`);
    }
    const length = alley.axis === "z" ? alley.d : alley.w;
    for (let i = 0; i < length; i++) {
      const sides = alley.axis === "z" ? [terrainAt(alley.x - 1, alley.z + i), terrainAt(alley.x + alley.w, alley.z + i)] : [terrainAt(alley.x + i, alley.z - 1), terrainAt(alley.x + i, alley.z + alley.d)];
      if (sides.some((terrain) => terrain !== Terrain.BUILDING)) {
        fail(label, `alley at (${alley.x}, ${alley.z}) is wider than ${MAP.ALLEY_WIDTH} cells`);
        break;
      }
    }
  }
}
var walkableCounts = [];
var alleyTotal = 0;
for (let seed = 1; seed <= SEEDS; seed++) {
  const city = generateCity(new Rng(seed));
  walkableCounts.push(checkStreets(city, `seed ${seed}`));
  checkAlleys(city, `seed ${seed}`);
  alleyTotal += city.alleys.length;
}
var sorted = [...walkableCounts].sort((a, b) => a - b);
var mean = walkableCounts.reduce((sum, value) => sum + value, 0) / walkableCounts.length;
var total = MAP.SIZE * MAP.SIZE;
console.log(`${SEEDS} random cities, ${MAP.SIZE}\xD7${MAP.SIZE}`);
console.log(
  `  walkable cells: min ${sorted[0]}, mean ${mean.toFixed(0)}, max ${sorted[sorted.length - 1]} (${(mean / total * 100).toFixed(0)}% of the map)`
);
console.log(`  alleys per city: ${(alleyTotal / SEEDS).toFixed(1)}`);
var east = loadEast();
var eastWalkable = checkStreets(east, "\u53F0\u5317\u6771\u5340");
var { width, height } = east.grid;
console.log(`\u53F0\u5317\u6771\u5340, ${width}\xD7${height}`);
console.log(`  walkable cells: ${eastWalkable} (${(eastWalkable / (width * height) * 100).toFixed(0)}% of the map), ${east.lots.length} lots`);
if (failures.length > 0) {
  console.error(`
${failures.length} problems:
  ${failures.join("\n  ")}`);
  process.exit(1);
}
console.log("all checks passed");
